package com.javamentor.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Report generated by the Auditor/Critic AI Agent after evaluating the Mentor's response.
 * Evaluates against the 100-mark assignment criteria:
 * - Phase 1 Completeness (Theory, JVM runtime dynamics, API/keywords, real-world context)
 * - Phase 2 Completeness (Pseudocode, Edge cases, Time & Space Complexity)
 * - Phase 3 Quality (Zero truncation, fully compilable code, main method with 2+ test scenarios)
 */
public class AuditReport {

    private final boolean passed;
    private final int rubricScore; // 0 - 100
    private final boolean phase1Valid;
    private final boolean phase2Valid;
    private final boolean phase3Valid;
    private final boolean zeroTruncation;
    private final boolean hasTestScenarios;
    private final List<String> feedbackNotes;

    public AuditReport(boolean passed, int rubricScore, boolean phase1Valid, boolean phase2Valid,
                       boolean phase3Valid, boolean zeroTruncation, boolean hasTestScenarios,
                       List<String> feedbackNotes) {
        this.passed = passed;
        this.rubricScore = rubricScore;
        this.phase1Valid = phase1Valid;
        this.phase2Valid = phase2Valid;
        this.phase3Valid = phase3Valid;
        this.zeroTruncation = zeroTruncation;
        this.hasTestScenarios = hasTestScenarios;
        this.feedbackNotes = feedbackNotes != null ? new ArrayList<>(feedbackNotes) : new ArrayList<>();
    }

    public boolean isPassed() {
        return passed;
    }

    public int getRubricScore() {
        return rubricScore;
    }

    public boolean isPhase1Valid() {
        return phase1Valid;
    }

    public boolean isPhase2Valid() {
        return phase2Valid;
    }

    public boolean isPhase3Valid() {
        return phase3Valid;
    }

    public boolean isZeroTruncation() {
        return zeroTruncation;
    }

    public boolean isHasTestScenarios() {
        return hasTestScenarios;
    }

    public List<String> getFeedbackNotes() {
        return Collections.unmodifiableList(feedbackNotes);
    }

    public String toSummary() {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("Auditor Evaluation Score: %d/100 [%s]\n", rubricScore, passed ? "PASSED" : "NEEDS REFINEMENT"));
        sb.append(String.format("  - Phase 1 (Conceptual Breakdown): %s\n", phase1Valid ? "OK" : "MISSING/INCOMPLETE"));
        sb.append(String.format("  - Phase 2 (Algorithmic Logic):    %s\n", phase2Valid ? "OK" : "MISSING/INCOMPLETE"));
        sb.append(String.format("  - Phase 3 (Runnable Java Code):   %s\n", phase3Valid ? "OK" : "MISSING/INCOMPLETE"));
        sb.append(String.format("  - Zero-Truncation Enforced:       %s\n", zeroTruncation ? "OK (No placeholders)" : "FAILED (Contains placeholders)"));
        sb.append(String.format("  - Test Scenarios in main():       %s\n", hasTestScenarios ? "OK (2+ scenarios)" : "WARNING (Scenarios unclear)"));
        if (!feedbackNotes.isEmpty()) {
            sb.append("  - Auditor Observations:\n");
            for (String note : feedbackNotes) {
                sb.append("    * ").append(note).append("\n");
            }
        }
        return sb.toString();
    }
}

